// Two's complement, overflow, and floating-point imprecision

// 1) The famous floating-point surprise
console.log(0.1 + 0.2);               // 0.30000000000000004
console.log(0.1 + 0.2 === 0.3);       // false

// Safe float comparison: use an epsilon tolerance
const nearlyEqual = (a, b) => Math.abs(a - b) < Number.EPSILON;
console.log(nearlyEqual(0.1 + 0.2, 0.3)); // true

// 2) Two's complement negation on 8 bits: flip bits, add 1
function negate8(n) {
  return ((~n) + 1) & 0xFF;  // keep only 8 bits
}
console.log(negate8(5).toString(2).padStart(8, '0')); // 11111011  (−5 pattern)

// 3) Simulated 8-bit unsigned overflow (wrap modulo 256)
function addU8(a, b) { return (a + b) & 0xFF; }
console.log(addU8(255, 1)); // 0  -> wraps around like a clock

// Integer ranges for n bits
// Unsigned:         0 ..  2^n - 1
// Two's complement: -2^(n-1) .. 2^(n-1) - 1   (asymmetric: one extra negative)
const ranges = {
  int8:  { min: -(2 ** 7),  max: 2 ** 7  - 1 },  // -128 .. 127
  uint8: { min: 0,           max: 2 ** 8  - 1 },  //    0 .. 255
  int32: { min: -(2 ** 31), max: 2 ** 31 - 1 },  // -2 147 483 648 .. 2 147 483 647
};

// IEEE 754 double (64-bit) layout
const ieee754Double = {
  signBits:     1,   // 0 = positive, 1 = negative
  exponentBits: 11,  // biased exponent (bias 1023)
  fractionBits: 52,  // mantissa; implicit leading 1 for normalised values
  // reconstructed value: (-1)^sign * 1.fraction * 2^(exponent - 1023)
};

